resource appPlan 'Microsoft.Web/serverfarms@2023-01-01' = {
  name: 'prod-plan'
  location: resourceGroup().location
  sku: {
    name: 'P1v3'
    tier: 'PremiumV3'
    capacity: 3
  }
  kind: 'app'
  properties: {
    reserved: true
    zoneRedundant: true
  }
}

// zoneRedundant: true instructs Azure to place instances
// across Availability Zones automatically. Without it, all
// instances could land in a single zone and fail together.
